`IPair` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 3
  if (argc == 0) {
    f <- IPair__SWIG_0; 
  } else if (argc == 1) {
    if ( extends(argtypes[1], '_p_std__pairT_int_int_t') && length(argv[[1]]) == 1 ) {
      f <- IPair__SWIG_2; 
    }
  } else if (argc == 2) {
    if (( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) && ( (is.integer(argv[[2]]) || is.numeric(argv[[2]])) && length(argv[[2]]) == 1 )) {
      f <- IPair__SWIG_1; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for IPair with argtypes (",toString(argtypes),")");
  };
  f(...);
}

