# Start of new_Ridge

`Ridge__SWIG_0` = function(data, formula, lambda, n_lambda, cv_folds, standardize, seed)
{
  if (inherits(data, "ExternalReference")) data = slot(data,"ref"); 
  formula = as(formula, "character"); 
  
  n_lambda = as.integer(n_lambda);
  
  if(length(n_lambda) > 1) {
    warning("using only the first element of n_lambda");
  };
  
  cv_folds = as.integer(cv_folds);
  
  if(length(cv_folds) > 1) {
    warning("using only the first element of cv_folds");
  };
  
  standardize = as.logical(standardize);
  seed = as.integer(seed);
  
  if(length(seed) > 1) {
    warning("using only the first element of seed");
  };
  
  ;ans = .Call('R_swig_new_Ridge__SWIG_0', data, formula, lambda, n_lambda, cv_folds, standardize, seed, PACKAGE='datamunger');
  ans <- if (is.null(ans)) ans
  else new("_p_datamunge__Ridge", ref=ans);
  
  reg.finalizer(ans@ref, delete_Ridge);
  ans
  
}

