{
  accessorFuns = list('formula_text' = Ridge_formula_text, 'has_intercept' = Ridge_has_intercept, 'predictor_names' = Ridge_predictor_names, 'observations' = Ridge_observations, 'lambda' = Ridge_lambda, 'lambda_was_selected' = Ridge_lambda_was_selected, 'lambda_path' = Ridge_lambda_path, 'cv_mean_squared_error' = Ridge_cv_mean_squared_error, 'coefficients' = Ridge_coefficients, 'intercept' = Ridge_intercept, 'fitted_values' = Ridge_fitted_values, 'residuals' = Ridge_residuals, 'r_squared' = Ridge_r_squared, 'rmse' = Ridge_rmse, 'summary' = Ridge_summary, 'print_summary' = Ridge_print_summary, 'predict' = Ridge_predict, 'plot_coefficient_path' = Ridge_plot_coefficient_path, 'plot_cv_curve' = Ridge_plot_cv_curve, 'plot_predicted_vs_actual' = Ridge_plot_predicted_vs_actual, 'plot_residuals_vs_fitted' = Ridge_plot_residuals_vs_fitted);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
