setMethod('$', '_p_datamunge__Lasso', function(x, name)

{
  accessorFuns = list('formula_text' = Lasso_formula_text, 'has_intercept' = Lasso_has_intercept, 'predictor_names' = Lasso_predictor_names, 'observations' = Lasso_observations, 'lambda' = Lasso_lambda, 'lambda_was_selected' = Lasso_lambda_was_selected, 'lambda_path' = Lasso_lambda_path, 'cv_mean_squared_error' = Lasso_cv_mean_squared_error, 'coefficients' = Lasso_coefficients, 'intercept' = Lasso_intercept, 'non_zero_coefficients' = Lasso_non_zero_coefficients, 'fitted_values' = Lasso_fitted_values, 'residuals' = Lasso_residuals, 'r_squared' = Lasso_r_squared, 'rmse' = Lasso_rmse, 'summary' = Lasso_summary, 'print_summary' = Lasso_print_summary, 'predict' = Lasso_predict, 'plot_coefficient_path' = Lasso_plot_coefficient_path, 'plot_cv_curve' = Lasso_plot_cv_curve, 'plot_predicted_vs_actual' = Lasso_plot_predicted_vs_actual, 'plot_residuals_vs_fitted' = Lasso_plot_residuals_vs_fitted);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
# end of accessor method for datamunge::Lasso
setMethod('delete', '_p_datamunge__Lasso', function(obj) {delete_datamunge__Lasso(obj)})
