`KNNClassifier__SWIG_0` = function(data, formula, k, metric, weighted, standardize)
{
  if (inherits(data, "ExternalReference")) data = slot(data,"ref"); 
  formula = as(formula, "character"); 
  k = as.integer(k);
  
  if(length(k) > 1) {
    warning("using only the first element of k");
  };
  
  metric = as(metric, "character"); 
  weighted = as.logical(weighted);
  standardize = as.logical(standardize);
  ;ans = .Call('R_swig_new_KNNClassifier__SWIG_0', data, formula, k, metric, weighted, standardize, PACKAGE='datamunger');
  ans <- if (is.null(ans)) ans
  else new("_p_datamunge__KNNClassifier", ref=ans);
  
  reg.finalizer(ans@ref, delete_KNNClassifier);
  ans
  
}

