    }
  } else if (argc == 4) {
    if (( extends(argtypes[1], '_p_datamunge__XGBoostClassifier') || is.null(argv[[1]]) ) && ( is.character(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.character(argv[[3]]) && length(argv[[3]]) == 1 ) && ( (is.integer(argv[[4]]) || is.numeric(argv[[4]])) && length(argv[[4]]) == 1 )) {
      f <- XGBoostClassifier_plot_decision_regions__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for XGBoostClassifier_plot_decision_regions with argtypes (",toString(argtypes),")");
  };
  f(...);
}

