setMethod('$', '_p_datamunge__Dual', function(x, name)

{
  accessorFuns = list('value' = Dual_value, 'derivative' = Dual_derivative, 'add' = Dual_add, 'subtract' = Dual_subtract, 'multiply' = Dual_multiply, 'divide' = Dual_divide, 'negate' = Dual_negate, 'add_scalar' = Dual_add_scalar, 'subtract_scalar' = Dual_subtract_scalar, 'multiply_scalar' = Dual_multiply_scalar, 'divide_scalar' = Dual_divide_scalar, 'pow' = Dual_pow, 'exp' = Dual_exp, 'log' = Dual_log, 'sqrt' = Dual_sqrt, 'sin' = Dual_sin, 'cos' = Dual_cos, 'tan' = Dual_tan, 'tanh' = Dual_tanh, 'abs' = Dual_abs);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
# end of accessor method for datamunge::Dual
